```java
public class LinkedList {
    private Node head; // 첫 노드를 가리키는 포인터

    private class Node {
        int data; // 저장할 데이터
        Node next; // 다음 노드를 가리키는 포인터

        public Node(int data) {
            this.data = data;
            this.next = null;
        }
    }

    // 리스트 끝에 데이터 추가
    public void add(int data) {
        if (head == null) { // 리스트가 비어 있다면
            head = new Node(data);
        } else {
            Node current = head;
            while (current.next != null) {
                current = current.next;
            }
            current.next = new Node(data);
        }
    }

    // 리스트에서 데이터 삭제
    public boolean remove(int data) {
        if (head == null) { // 리스트가 비어 있다면
            return false;
        } else if (head.data == data) { // 첫 노드의 데이터가 같다면
            head = head.next;
            return true;
        } else {
            Node current = head;
            while (current.next != null) {
                if (current.next.data == data) { // 다음 노드의 데이터가 같다면
                    current.next = current.next.next;
                    return true;
                }
                current = current.next;
            }
            return false;
        }
    }

    // 리스트 출력
    public void print() {
        Node current = head;
        while (current != null) {
            System.out.print(current.data + " ");
            current = current.next;
        }
        System.out.println();
    }
}
```

